import sys

DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def to_base(n, base):
    out = ""
    while n > 0:
        out = DIGITS[n % base] + out
        n //= base
    return out


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            print("ERROR")
            continue
        number, src_str, dst_str = parts
        try:
            src = int(src_str)
            dst = int(dst_str)
        except ValueError:
            print("ERROR")
            continue
        if not (2 <= src <= 36 and 2 <= dst <= 36):
            print("ERROR")
            continue
        try:
            value = int(number, src)
        except ValueError:
            print("ERROR")
            continue
        if value < 0:
            print("-" + to_base(abs(value), dst))
        else:
            result = to_base(value, dst)
            print(result if result else "0")


if __name__ == "__main__":
    main()
